    public void ApplyCoupon_TotalNeverGoesNegative()
    {
        _cart.AddItem("SKU-001", 1, 5.00m);
        _cart.ApplyCoupon("SAVE10");

        var total = _cart.CalculateTotal();
        Assert.IsTrue(total >= 0m, $"Total should not be negative, got {total}");
    }
